#include <iomanip>
#include <iostream>
#include <string>

int main() {
    const char SOH = '\x01';  // FIX's field separator, code 1
    const std::string msg = std::string("8=FIX.4.2") + SOH + "35=D" + SOH + "55=AAPL" + SOH + "38=100" + SOH;
    std::cout << "bytes: " << msg.size() << '\n';

    int fields = 0;
    for (char c : msg) {
        if (c == SOH) {
            ++fields;
        }
    }
    std::cout << "fields: " << fields << '\n';

    std::cout << "hex of field 1:";
    for (std::size_t i = 0; i <= msg.find(SOH); ++i) {
        const int code = static_cast<unsigned char>(msg[i]);
        std::cout << ' ' << std::hex << std::uppercase << std::setw(2) << std::setfill('0') << code;
    }
    std::cout << std::dec << '\n';

    std::string readable;
    for (char c : msg) {
        readable += (c == SOH) ? '|' : c;
    }
    std::cout << "readable: " << readable << '\n';
    return 0;
}

