#include <iostream>
#include <string>
#include <vector>

int main() {
    const std::vector<std::string> names = {"AAPL", "Zürich", "€100", "Nestlé", "Ελλάδα"};
    for (const auto& name : names) {
        int points = 0;
        for (char c : name) {
            const int code = static_cast<unsigned char>(c);
            if (code < 0x80 || code >= 0xC0) {  // not a continuation byte
                ++points;
            }
        }
        const std::string padding(8 - points, ' ');  // pad to 8 code points, not 8 bytes
        std::cout << name << padding << "| " << name.size() << " bytes, " << points << " code points\n";
    }
    return 0;
}

