#include <iomanip>
#include <iostream>
#include <string>

int main() {
    const std::string text = "Zé€🚀";
    std::size_t i = 0;
    while (i < text.size()) {
        const int lead = static_cast<unsigned char>(text[i]);
        int length = 1;
        int point = lead;
        if (lead >= 0xF0) {
            length = 4;
            point = lead - 0xF0;
        } else if (lead >= 0xE0) {
            length = 3;
            point = lead - 0xE0;
        } else if (lead >= 0xC0) {
            length = 2;
            point = lead - 0xC0;
        }
        for (int k = 1; k < length; ++k) {
            point = point * 64 + (static_cast<unsigned char>(text[i + k]) - 0x80);
        }
        std::cout << "U+" << std::hex << std::uppercase << std::setw(4) << std::setfill('0') << point
                  << std::dec << " in " << length << " byte(s)\n";
        i += length;
    }

    const std::string name = "Société Générale";
    std::size_t cut = 8;  // the column holds 8 bytes
    while (cut > 0 && cut < name.size()) {
        const int code = static_cast<unsigned char>(name[cut]);
        if (code < 0x80 || code >= 0xC0) {
            break;  // a character starts here, so cutting here is safe
        }
        --cut;
    }
    std::cout << "cut at " << cut << ": " << name.substr(0, cut) << '\n';
    return 0;
}

