#include <iostream>
#include <regex>
#include <string>
#include <vector>

int main() {
    const std::regex symbolPattern(R"([A-Z]{1,5}(\.[A-Z])?)");  // built once, used many times
    const std::vector<std::string> symbols = {"AAPL", "BRK.B", "msft", "GOOGLE", "ÉDF"};
    std::cout << std::boolalpha;
    for (const auto& s : symbols) {
        std::cout << s << " valid: " << std::regex_match(s, symbolPattern) << '\n';
    }

    const std::regex fillPattern(R"(FILL ([A-Z.]+) (\d+) @ (\d+\.\d+))");
    const std::string line = "09:30:00.125 [gw2] FILL AAPL 100 @ 192.75 venue=XNAS";
    std::smatch m;
    if (std::regex_search(line, m, fillPattern)) {
        std::cout << "match: " << m[0] << '\n';
        std::cout << "symbol: " << m[1] << ", qty: " << std::stoi(m.str(2)) << ", price: " << m[3] << '\n';
    }
    std::cout << "whole line matches: " << std::regex_match(line, fillPattern) << '\n';
    return 0;
}

