#include <iomanip>
#include <iostream>
#include <regex>
#include <string>
#include <vector>

int main() {
    const std::regex isinPattern(R"([A-Z]{2}[A-Z0-9]{9}\d)");
    const std::vector<std::string> isins = {"US0378331005", "us0378331005", "US037833100", "DE000BAY0017"};
    std::cout << std::boolalpha;
    for (const auto& isin : isins) {
        std::cout << isin << " valid: " << std::regex_match(isin, isinPattern) << '\n';
    }

    const std::string line = "10:15:02.500 QUOTE MSFT bid=410.20 ask=410.30 src=feedA";
    const std::regex quotePattern(R"(QUOTE ([A-Z.]+) bid=(\d+\.\d+) ask=(\d+\.\d+))");
    std::smatch m;
    if (std::regex_search(line, m, quotePattern)) {
        std::cout << "symbol: " << m[1] << '\n';
        std::cout << "bid: " << m[2] << " ask: " << m[3] << '\n';
        const double spread = std::stod(m.str(3)) - std::stod(m.str(2));
        std::cout << std::fixed << std::setprecision(2) << "spread: " << spread << '\n';
    }
    return 0;
}
